import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k, c = data[0], data[1], data[2]
    a = data[3:3 + n]
    total = sum(a)

    if c == 1:
        print(total - sum(sorted(a)[:k]))
        return

    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    slack = n - k * c
    dp = [
        prefix[x + c] - prefix[x]
        for x in range(slack + 1)
    ]

    for block in range(1, k):
        offset = block * c
        next_dp = [0] * (slack + 1)
        best = float('inf')

        for x in range(slack + 1):
            if dp[x] < best:
                best = dp[x]
            start = offset + x
            next_dp[x] = best + prefix[start + c] - prefix[start]

        dp = next_dp

    print(total - min(dp))

if __name__ == "__main__":
    main()
